WITH exploded AS (SELECT id, created_at, coupon_codes, pos + 1 AS line_no, rec.product_id, rec.qty, rec.price FROM carts LATERAL VIEW OUTER POSEXPLODE(items) x AS pos, rec) SELECT product_id, line_no, PERCENTILE_APPROX(price, 0.9) AS price_p90, APPROX_PERCENTILE(product_id, 0.9) AS product_id_p90, MIN(created_at) AS first_seen, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY PERCENTILE_APPROX(price, 0.9) DESC) AS price_p90_dense_rank FROM exploded GROUP BY 1, 2
